-- =============================================================================
-- SITELINE dummy data for the Thesis-Backend schema (DEVELOPMENT / DEMO ONLY)
--
--   * Run AFTER 20261017000002_thesis_backend_schema.sql, as the postgres role
--     (Supabase SQL Editor). It inserts 11 accounts, 7 projects, 6 subcontractor companies,
--     phase teams, documents (tiny real PDFs/PNGs in stored_files), progress
--     history, checklists, pending reviews and notifications.
--   * EVERY demo account uses the password  Password@123
--     Do not load this into a production database.
--   * Safe to re-run: it replaces the demo data, but stops without changes if the
--     database contains any account that is not one of these demo accounts.
--
--   admin   patricia.domingo@10builders.com
--   opm     renz.villaverde@10builders.com   lea.fernandez@10builders.com
--   spm     karlo.espiritu@ / rafael.mercado@ / mikaela.bautista@ /
--           diego.salvador@ / bea.concepcion@10builders.com   (jomar.reyes@ is suspended)
--   client  f.uy@aldenheights-hoa.com   maria.santos@rosariabiz.ph
-- =============================================================================

do $$
begin
  if to_regclass('public.users') is null or not exists (select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'users' and column_name = 'password_hash') then
    raise exception 'Run the Thesis-Backend schema migration first.';
  end if;
  if exists (select 1 from public.users) then
    -- Re-running replaces the demo data, but never touches a database with real accounts.
    if exists (select 1 from public.users where lower(email::text) not in ('patricia.domingo@10builders.com', 'renz.villaverde@10builders.com', 'lea.fernandez@10builders.com', 'karlo.espiritu@10builders.com', 'rafael.mercado@10builders.com', 'mikaela.bautista@10builders.com', 'diego.salvador@10builders.com', 'bea.concepcion@10builders.com', 'jomar.reyes@10builders.com', 'f.uy@aldenheights-hoa.com', 'maria.santos@rosariabiz.ph')) then
      raise exception 'The database contains accounts that are not demo accounts. Nothing was changed.';
    end if;
    truncate table public.users, public.projects, public.subcontractors, public.stored_files, public.activity_log
      restart identity cascade;
  end if;
end $$;

